import React from 'react';
import { Card } from 'react-bootstrap';

function FileSystem() {
  return (
    <Card>
      <Card.Header>Virtual File System</Card.Header>
      <Card.Body>
        <p>File system browser coming soon...</p>
      </Card.Body>
    </Card>
  );
}

export default FileSystem;
